package com.jovx.api.catalog.storage;

import java.io.IOException;
import java.io.UncheckedIOException;
import java.nio.file.*;
import java.util.Optional;
import java.util.regex.Pattern;

/** Development store: files under one directory, served by GET /api/v1/public/images/{key}. */
public final class LocalImageStore implements ImageStore {
  /** Keys are generated by the server: products/{uuid}/{uuid}.jpg — nothing else is ever read. */
  static final Pattern KEY = Pattern.compile("products/[0-9a-f-]{36}/[0-9a-f-]{36}\\.jpg");
  private final Path root;

  public LocalImageStore(Path root) {
    this.root = root.toAbsolutePath().normalize();
  }

  public boolean configured() { return true; }

  private Path path(String key) {
    if (!KEY.matcher(key).matches()) throw new IllegalArgumentException("Invalid image key");
    var path = root.resolve(key).normalize();
    if (!path.startsWith(root)) throw new IllegalArgumentException("Invalid image key");
    return path;
  }

  public void put(String key, byte[] bytes, String contentType) {
    try {
      var path = path(key);
      Files.createDirectories(path.getParent());
      Files.write(path, bytes, StandardOpenOption.CREATE_NEW);
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }

  public void delete(String key) {
    try { Files.deleteIfExists(path(key)); } catch (IOException e) { throw new UncheckedIOException(e); }
  }

  public String publicUrl(String key) {
    return "/api/v1/public/images/" + key;
  }

  public Optional<byte[]> read(String key) {
    try {
      var path = path(key);
      return Files.isRegularFile(path) ? Optional.of(Files.readAllBytes(path)) : Optional.empty();
    } catch (IllegalArgumentException e) {
      return Optional.empty();
    } catch (IOException e) {
      throw new UncheckedIOException(e);
    }
  }
}
